func main() {
	var opt options
	flag.BoolVar(&opt.ai, "ai", false, "generate test cases using AI (requires Ollama)")
	flag.StringVar(&opt.aiEndpoint, "ai-endpoint", "http://localhost:11434", "Ollama API endpoint")
	flag.IntVar(&opt.aiMax, "ai-max-cases", 10, "maximum number of test cases to generate with AI")
	flag.IntVar(&opt.aiMin, "ai-min-cases", 3, "minimum number of test cases to generate with AI")
	flag.StringVar(&opt.aiModel, "ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
	flag.BoolVar(&opt.all, "all", false, "generate tests for all functions and methods")
	flag.StringVar(&opt.excl, "excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
	flag.BoolVar(&opt.exported, "exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
	flag.BoolVar(&opt.printInputs, "i", false, "print test inputs in error messages")
	flag.BoolVar(&opt.named, "named", false, "switch table tests from using slice to map (with test name for the key)")
	flag.BoolVar(&opt.nosubtests, "nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
	flag.StringVar(&opt.only, "only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
	flag.BoolVar(&opt.parallel, "parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	flag.StringVar(&opt.templateName, "template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
	flag.StringVar(&opt.templateDir, "template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
	flag.StringVar(&opt.templateParams, "template_params", "", "read external parameters to template by json with stdin")
	flag.StringVar(&opt.templateParamsFile, "template_params_file", "", "read external parameters to template by json with file")
	flag.BoolVar(&opt.useGoCmp, "use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	flag.BoolVar(&opt.version, "version", false, "print version information and exit")
	flag.BoolVar(&opt.write, "w", false, "write output to (test) files instead of stdout")
	flag.Parse()

	if opt.version {
		fmt.Println("gotests v0.0.0-20260303205902-f3b63d74369a")
		fmt.Println("Go version: go1.24.5")
		fmt.Println("Git commit: f3b63d74369a8c405a9a3990a656a278a4f9096f")
		fmt.Println("Build time: 2026-03-03T20:59:02Z")
		return
	}

	if opt.ai {
		fmt.Fprintf(os.Stderr, "⚠️  WARNING: Function source code will be sent to AI provider at %s\n", opt.aiEndpoint)
		fmt.Fprintln(os.Stderr, "   Ensure your code does not contain secrets or sensitive information.")
		fmt.Fprintln(os.Stderr)
		if opt.aiMin > opt.aiMax {
			fmt.Fprintf(os.Stderr, "Error: -ai-min-cases (%d) cannot be greater than -ai-max-cases (%d)\n", opt.aiMin, opt.aiMax)
			os.Exit(1)
		}
	}

	if !opt.all && opt.only == "" && opt.excl == "" && !opt.exported {
		fmt.Println("Please specify either the -only, -excl, -exported, or -all flag")
		return
	}

	var onlyRE, exclRE *regexp.Regexp
	var err error
	if opt.only != "" {
		onlyRE, err = regexp.Compile(opt.only)
		if err != nil {
			fmt.Printf("Invalid -only regex: %v\n", err)
			return
		}
	}
	if opt.excl != "" {
		exclRE, err = regexp.Compile(opt.excl)
		if err != nil {
			fmt.Printf("Invalid -excl regex: %v\n", err)
			return
		}
	}

	if opt.templateName == "" {
		opt.templateName = os.Getenv("GOTESTS_TEMPLATE")
	}
	if opt.templateDir == "" {
		opt.templateDir = os.Getenv("GOTESTS_TEMPLATE_DIR")
	}

	if opt.templateParamsFile != "" {
		b, e := ioutil.ReadFile(opt.templateParamsFile)
		if e != nil {
			fmt.Printf("Failed to read from %s ,err %v", opt.templateParamsFile, e)
			return
		}
		var v interface{}
		if e := json.Unmarshal(b, &v); e != nil {
			fmt.Printf("Failed to umarshal %s er %v", opt.templateParamsFile, e)
			return
		}
	}
	if opt.templateParams != "" {
		var v interface{}
		if e := json.Unmarshal([]byte(opt.templateParams), &v); e != nil {
			fmt.Printf("Failed to unmarshal template_params JSON: %v", e)
			return
		}
	}

	if flag.NArg() == 0 {
		fmt.Println("Please specify a file or directory containing the source")
		return
	}

	if opt.templateDir != "" {
		ents, e := ioutil.ReadDir(opt.templateDir)
		if e != nil {
			fmt.Printf("output.Process: loading custom templates: ioutil.ReadDir: open %s: %v\n", opt.templateDir, e)
			return
		}
		has := false
		for _, ent := range ents {
			if !ent.IsDir() && strings.HasSuffix(ent.Name(), ".tmpl") {
				has = true
				break
			}
		}
		if !has {
			fmt.Println("output.Process: loading custom templates: tmpls.ParseFiles: template: no files named in call to ParseFiles")
			return
		}
	} else if opt.templateName != "" && opt.templateName != "testify" {
		fmt.Println("output.Process: loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")
		return
	}

	paths, pathKinds, collectErr := collectInputs(flag.Args())
	if collectErr != "" {
		fmt.Println(collectErr)
		fmt.Println()
		return
	}

	// Process each command-line argument as the original command does: explicit files
	// get per-file "No tests" messages; directories report at directory granularity.
	idx := 0
	for argNum, arg := range flag.Args() {
		kind := pathKinds[argNum]
		files := paths[argNum]
		anyGenerated := false
		var pending []fileResult
		for _, p := range files {
			res := processFile(p, arg, kind == "file", &opt, onlyRE, exclRE)
			if res.Err != "" {
				fmt.Println(res.Err)
				return
			}
			if len(res.Generated) > 0 {
				anyGenerated = true
				pending = append(pending, res)
			} else if kind == "file" {
				fmt.Printf("No tests generated for %s\n", arg)
			}
			idx++
		}
		if kind != "file" && !anyGenerated {
			fmt.Printf("No tests generated for %s\n", arg)
		}
		for _, res := range pending {
			if opt.ai {
				fmt.Printf("output.Process: AI provider ollama is not available - ensure Ollama is running at %s\n", opt.aiEndpoint)
				return
			}
			for _, name := range res.Generated {
				fmt.Printf("Generated %s\n", name)
			}
			if opt.write {
				_ = ioutil.WriteFile(res.TargetPath, []byte(res.Content), 0644)
			} else {
				fmt.Print(res.Content)
			}
		}
	}
	_ = idx
}

func collectInputs(args []string) ([][]string, []string, string) {
	out := make([][]string, len(args))
	kinds := make([]string, len(args))
	for i, arg := range args {
		if strings.HasSuffix(arg, "/...") {
			root := strings.TrimSuffix(arg, "/...")
			if root == "" {
				root = "."
			}
			st, err := os.Stat(root)
			if err != nil {
				abs, _ := filepath.Abs(root)
				return nil, nil, fmt.Sprintf("input.Files: os.Stat: stat %s: no such file or directory", abs)
			}
			if !st.IsDir() {
				out[i] = []string{root}
				kinds[i] = "file"
				continue
			}
			var files []string
			filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
				if err != nil || info == nil {
					return nil
				}
				if info.IsDir() {
					name := info.Name()
					if name == ".git" || name == "vendor" {
						return filepath.SkipDir
					}
					return nil
				}
				if isSourceGo(path) {
					files = append(files, path)
				}
				return nil
			})
			sort.Strings(files)
			out[i] = files
			kinds[i] = "dir"
			continue
		}
		st, err := os.Stat(arg)
		if err != nil {
			abs, _ := filepath.Abs(arg)
			return nil, nil, fmt.Sprintf("input.Files: os.Stat: stat %s: no such file or directory", abs)
		}
		if st.IsDir() {
			ents, _ := ioutil.ReadDir(arg)
			var files []string
			for _, ent := range ents {
				if !ent.IsDir() {
					p := filepath.Join(arg, ent.Name())
					if isSourceGo(p) {
						files = append(files, p)
					}
				}
			}
			sort.Strings(files)
			out[i] = files
			kinds[i] = "dir"
		} else {
			out[i] = []string{arg}
			kinds[i] = "file"
		}
	}
	return out, kinds, ""
}

func isSourceGo(path string) bool {
	return strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go")
}

func processFile(path, displayArg string, explicitFile bool, opt *options, onlyRE, exclRE *regexp.Regexp) fileResult {
	res := fileResult{Path: path, TargetPath: testPath(path)}
	if strings.HasSuffix(path, "_test.go") {
		res.NoTests = true
		return res
	}
	pkg, parseErr := loadPackage(filepath.Dir(path))
	if parseErr != nil {
		// Re-parse the target to reproduce the common parse error form.
		fset := token.NewFileSet()
		_, e := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if e != nil {
			res.Err = fmt.Sprintf("Parser.Parse source file: target parser.ParseFile(): %v", e)
		} else {
			res.Err = fmt.Sprintf("Parser.Parse source file: target parser.ParseFile(): %v", parseErr)
		}
		return res
	}
	src := pkg.Files[cleanPath(path)]
	if src == nil {
		fset := token.NewFileSet()
		var e error
		src, e = parser.ParseFile(fset, path, nil, parser.ParseComments)
		if e != nil {
			res.Err = fmt.Sprintf("Parser.Parse source file: target parser.ParseFile(): %v", e)
			return res
		}
	}
	existingPkg, existingBody, existingTests, existingImports := readExistingTest(res.TargetPath)
	pkgName := src.Name.Name
	if existingPkg != "" {
		pkgName = existingPkg
	}

	var funcs []funcInfo
	for _, decl := range src.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Name == nil {
			continue
		}
		fi := buildFuncInfo(fd, pkg)
		if !selectFunc(fi, opt, onlyRE, exclRE) {
			continue
		}
		if existingTests[fi.TestName] {
			continue
		}
		funcs = append(funcs, fi)
	}
	if len(funcs) == 0 {
		res.NoTests = true
		return res
	}
	for _, fi := range funcs {
		res.Generated = append(res.Generated, fi.TestName)
	}
	content, err := renderFile(pkgName, existingBody, existingImports, funcs, pkg, opt)
	if err != nil {
		res.Err = fmt.Sprintf("output.Process: imports.Process: %v", err)
		return res
	}
	res.Content = content
	return res
}

func cleanPath(p string) string {
	c, err := filepath.Abs(p)
	if err != nil {
		return filepath.Clean(p)
	}
	return c
}

func testPath(path string) string {
	if strings.HasSuffix(path, ".go") {
		return strings.TrimSuffix(path, ".go") + "_test.go"
	}
	return path + "_test.go"
}

func loadPackage(dir string) (*packageInfo, error) {
	fset := token.NewFileSet()
	pkg := &packageInfo{Dir: dir, Fset: fset, Types: map[string]*typeDef{}, Imports: map[string]importSpec{}, Files: map[string]*ast.File{}}
	ents, err := ioutil.ReadDir(dir)
	if err != nil {
		return pkg, err
	}
	for _, ent := range ents {
		if ent.IsDir() || !isSourceGo(ent.Name()) {
			continue
		}
		p := filepath.Join(dir, ent.Name())
		f, e := parser.ParseFile(fset, p, nil, parser.ParseComments)
		if e != nil {
			return pkg, e
		}
		pkg.Files[cleanPath(p)] = f
		for _, im := range f.Imports {
			path, _ := strconv.Unquote(im.Path.Value)
			name := ""
			if im.Name != nil {
				name = im.Name.Name
			}
			local := importLocal(name, path)
			spec := importSpec{Name: name, Path: path, Local: local}
			if name == "." || name == "_" {
				pkg.SpecialImps = append(pkg.SpecialImps, spec)
			} else if _, ok := pkg.Imports[local]; !ok {
				pkg.Imports[local] = spec
			}
		}
		for _, decl := range f.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, sp := range gd.Specs {
				ts, ok := sp.(*ast.TypeSpec)
				if !ok {
					continue
				}
				td := &typeDef{Name: ts.Name.Name, Expr: ts.Type, Alias: ts.Assign.IsValid()}
				if ts.TypeParams != nil {
					for _, fl := range ts.TypeParams.List {
						for _, n := range fl.Names {
							td.TypeParams = append(td.TypeParams, typeParam{Name: n.Name, Constraint: fl.Type})
						}
					}
				}
				pkg.Types[td.Name] = td
			}
		}
	}
	return pkg, nil
}

func importLocal(name, path string) string {
	if name != "" {
		return name
	}
	base := filepath.Base(path)
	base = strings.TrimSuffix(base, ".git")
	base = strings.ReplaceAll(base, "-", "_")
	return base
}

func readExistingTest(path string) (pkgName string, body string, tests map[string]bool, imports []importSpec) {
	tests = map[string]bool{}
	b, err := ioutil.ReadFile(path)
	if err != nil {
		return "", "", tests, nil
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, b, parser.ParseComments)
	if err != nil {
		// Keep raw body best-effort.
		return "", "", tests, nil
	}
	pkgName = f.Name.Name
	for _, im := range f.Imports {
		p, _ := strconv.Unquote(im.Path.Value)
		name := ""
		if im.Name != nil {
			name = im.Name.Name
		}
		imports = append(imports, importSpec{Name: name, Path: p, Local: importLocal(name, p)})
	}
	for _, d := range f.Decls {
		if fd, ok := d.(*ast.FuncDecl); ok && fd.Name != nil {
			tests[fd.Name.Name] = true
		}
	}
	// Remove package clause and import declarations from the original source.
	src := string(b)
	start := fset.Position(f.Name.End()).Offset
	if idx := strings.Index(src[start:], "\n"); idx >= 0 {
		start += idx + 1
	}
	type rng struct{ a, b int }
	var ranges []rng
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			ranges = append(ranges, rng{fset.Position(gd.Pos()).Offset, fset.Position(gd.End()).Offset})
		}
	}
	sort.Slice(ranges, func(i, j int) bool { return ranges[i].a < ranges[j].a })
	var out strings.Builder
	pos := start
	for _, r := range ranges {
		if r.a > pos {
			out.WriteString(src[pos:r.a])
		}
		pos = r.b
	}
	if pos < len(src) {
		out.WriteString(src[pos:])
	}
	body = strings.TrimSpace(out.String())
	return
}

func selectFunc(fi funcInfo, opt *options, onlyRE, exclRE *regexp.Regexp) bool {
	if opt.excl != "" {
		return !exclRE.MatchString(fi.MatchName)
	}
	if opt.exported {
		return isExported(fi.Name)
	}
	if opt.only != "" {
		return onlyRE.MatchString(fi.MatchName)
	}
	return opt.all
}

func isExported(name string) bool {
	r, _ := utf8.DecodeRuneInString(name)
	return unicode.IsUpper(r)
}

func buildFuncInfo(fd *ast.FuncDecl, pkg *packageInfo) funcInfo {
	fi := funcInfo{Name: fd.Name.Name, TypeParamNames: map[string]bool{}}
	if fd.Type.TypeParams != nil {
		for _, fl := range fd.Type.TypeParams.List {
			for _, n := range fl.Names {
				fi.TypeParamNames[n.Name] = true
				fi.TypeArgs = append(fi.TypeArgs, concreteForConstraint(fl.Type, pkg))
			}
		}
	}
	subst := map[string]string{}
	if fd.Type.TypeParams != nil {
		i := 0
		for _, fl := range fd.Type.TypeParams.List {
			for _, n := range fl.Names {
				if i < len(fi.TypeArgs) {
					subst[n.Name] = fi.TypeArgs[i]
				}
				i++
			}
		}
	}

	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		fi.IsMethod = true
		recvExpr := fd.Recv.List[0].Type
		fi.ReceiverPointer = false
		baseExpr := recvExpr
		if st, ok := recvExpr.(*ast.StarExpr); ok {
			fi.ReceiverPointer = true
			baseExpr = st.X
		}
		fi.ReceiverDisplay = nodeString(baseExpr)
		fi.ReceiverBase = receiverBaseName(baseExpr)
		fi.ReceiverVar = lowerFirst(fi.ReceiverBase)
		fi.MatchName = fi.ReceiverBase + fi.Name
		fi.TestName = "Test" + fi.ReceiverBase + "_" + fi.Name
		fi.DisplayName = fi.ReceiverDisplay + "." + fi.Name

		recvSubst := map[string]string{}
		if td := pkg.Types[fi.ReceiverBase]; td != nil && len(td.TypeParams) > 0 {
			fi.ReceiverIsGeneric = true
			args := make([]string, len(td.TypeParams))
			for i, tp := range td.TypeParams {
				args[i] = concreteForConstraint(tp.Constraint, pkg)
				recvSubst[tp.Name] = args[i]
			}
			fi.ReceiverType = fi.ReceiverBase + "[" + strings.Join(args, ", ") + "]"
		} else {
			fi.ReceiverType = fi.ReceiverBase
		}
		fields, isStruct := structFieldsFor(fi.ReceiverBase, pkg, recvSubst, map[string]bool{})
		fi.ReceiverIsStruct = isStruct
		if isStruct && len(fields) > 0 && !fi.ReceiverIsGeneric {
			fi.UseFields = true
			fi.Fields = fields
		}
	} else {
		fi.MatchName = fi.Name
		if isExported(fi.Name) {
			fi.TestName = "Test" + fi.Name
		} else {
			fi.TestName = "Test_" + fi.Name
		}
		fi.DisplayName = fi.Name
	}

	fi.Params = flattenParams(fd.Type.Params, subst, fi.TypeParamNames, pkg)
	fi.Results = flattenResults(fd.Type.Results, subst, fi.TypeParamNames, pkg)
	for i := range fi.Results {
		if fi.Results[i].Deep {
			fi.NeedsDeep = true
		}
	}
	return fi
}

func receiverBaseName(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.Ident:
		return x.Name
	case *ast.IndexExpr:
		return receiverBaseName(x.X)
	case *ast.IndexListExpr:
		return receiverBaseName(x.X)
	case *ast.SelectorExpr:
		return x.Sel.Name
	case *ast.StarExpr:
		return receiverBaseName(x.X)
	default:
		s := nodeString(e)
		if i := strings.Index(s, "["); i >= 0 {
			s = s[:i]
		}
		return strings.TrimPrefix(s, "*")
	}
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToLower(r)) + s[size:]
}

func flattenParams(fl *ast.FieldList, subst map[string]string, typeParams map[string]bool, pkg *packageInfo) []paramInfo {
	var out []paramInfo
	if fl == nil {
		return out
	}
	idx := 0
	for _, f := range fl.List {
		variadic := false
		typeExpr := f.Type
		if el, ok := f.Type.(*ast.Ellipsis); ok {
			variadic = true
			typeExpr = &ast.ArrayType{Elt: el.Elt}
		}
		names := f.Names
		if len(names) == 0 {
			name := fmt.Sprintf("in%d", idx)
			out = append(out, paramInfo{Name: name, Type: exprString(typeExpr, subst), Expr: typeExpr, Variadic: variadic, Index: idx, HasTypePar: exprHasTypeParam(f.Type, typeParams)})
			idx++
			continue
		}
		for _, n := range names {
			name := n.Name
			if name == "_" {
				name = fmt.Sprintf("in%d", idx)
			}
			out = append(out, paramInfo{Name: name, Type: exprString(typeExpr, subst), Expr: typeExpr, Variadic: variadic, Index: idx, HasTypePar: exprHasTypeParam(f.Type, typeParams)})
			idx++
		}
	}
	return out
}

func flattenResults(fl *ast.FieldList, subst map[string]string, typeParams map[string]bool, pkg *packageInfo) []resultInfo {
	var all []resultInfo
	if fl == nil {
		return all
	}
	idx := 0
	hasErr := false
	for _, f := range fl.List {
		names := f.Names
		if len(names) == 0 {
			typ := exprString(f.Type, subst)
			if typ == "error" {
				hasErr = true
			} else {
				all = append(all, resultInfo{Name: "", Type: typ, Expr: f.Type, Index: idx, HasTypePar: exprHasTypeParam(f.Type, typeParams)})
			}
			idx++
			continue
		}
		for _, n := range names {
			typ := exprString(f.Type, subst)
			if typ == "error" {
				hasErr = true
			} else {
				name := n.Name
				if name == "_" {
					name = ""
				}
				all = append(all, resultInfo{Name: name, Type: typ, Expr: f.Type, Index: idx, HasTypePar: exprHasTypeParam(f.Type, typeParams)})
			}
			idx++
		}
	}
	_ = hasErr
	for i := range all {
		all[i].Seq = i
		if all[i].Name != "" {
			suf := exportedSuffix(all[i].Name)
			all[i].VarName = "got" + suf
			all[i].WantName = "want" + suf
		} else if i == 0 {
			all[i].VarName = "got"
			all[i].WantName = "want"
		} else {
			all[i].VarName = fmt.Sprintf("got%d", i)
			all[i].WantName = fmt.Sprintf("want%d", i)
		}
		all[i].Deep = needsDeepCompare(all[i], pkg)
	}
	return all
}

func exportedSuffix(s string) string {
	if s == "" {
		return ""
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

func exprHasTypeParam(e ast.Expr, names map[string]bool) bool {
	if len(names) == 0 || e == nil {
		return false
	}
	found := false
	ast.Inspect(e, func(n ast.Node) bool {
		if id, ok := n.(*ast.Ident); ok && names[id.Name] {
			found = true
			return false
		}
		return true
	})
	return found
}

func nodeString(n interface{}) string {
	var b bytes.Buffer
	_ = format.Node(&b, token.NewFileSet(), n)
	return b.String()
}

func exprString(e ast.Expr, subst map[string]string) string {
	s := nodeString(e)
	for k, v := range subst {
		re := regexp.MustCompile(`\b` + regexp.QuoteMeta(k) + `\b`)
		s = re.ReplaceAllString(s, v)
	}
	return s
}

func concreteForConstraint(e ast.Expr, pkg *packageInfo) string {
	if e == nil {
		return "int"
	}
	switch x := e.(type) {
	case *ast.Ident:
		switch x.Name {
		case "any", "interface{}":
			return "int"
		case "comparable":
			return "string"
		default:
			// The observed binary falls back to string for named constraints/types.
			return "string"
		}
	case *ast.BinaryExpr:
		if x.Op == token.OR {
			return concreteForConstraint(x.X, pkg)
		}
	case *ast.UnaryExpr:
		if x.Op == token.TILDE {
			return concreteUnderlying(x.X)
		}
	case *ast.InterfaceType:
		if x.Methods == nil || len(x.Methods.List) == 0 {
			return "int"
		}
		// Prefer the first embedded type element if present.
		for _, f := range x.Methods.List {
			if len(f.Names) == 0 {
				return concreteForConstraint(f.Type, pkg)
			}
		}
		return "string"
	case *ast.ParenExpr:
		return concreteForConstraint(x.X, pkg)
	}
	return concreteUnderlying(e)
}

func concreteUnderlying(e ast.Expr) string {
	s := nodeString(e)
	s = strings.TrimPrefix(s, "~")
	if strings.Contains(s, "|") {
		s = strings.TrimSpace(strings.Split(s, "|")[0])
		s = strings.TrimPrefix(s, "~")
	}
	if s == "interface{}" {
		return "int"
	}
	if s == "comparable" {
		return "string"
	}
	if s == "any" {
		return "int"
	}
	return s
}

func structFieldsFor(name string, pkg *packageInfo, subst map[string]string, seen map[string]bool) ([]fieldInfo, bool) {
	if seen[name] {
		return nil, false
	}
	seen[name] = true
	td := pkg.Types[name]
	if td == nil {
		return nil, false
	}
	switch x := td.Expr.(type) {
	case *ast.StructType:
		var fields []fieldInfo
		if x.Fields != nil {
			for _, f := range x.Fields.List {
				typ := exprString(f.Type, subst)
				if len(f.Names) == 0 {
					fname := embeddedFieldName(f.Type)
					fields = append(fields, fieldInfo{Name: fname, Type: typ, Expr: f.Type})
				} else {
					for _, n := range f.Names {
						fields = append(fields, fieldInfo{Name: n.Name, Type: typ, Expr: f.Type})
					}
				}
			}
		}
		return fields, true
	case *ast.Ident:
		return structFieldsFor(x.Name, pkg, subst, seen)
	}
	return nil, false
}

func embeddedFieldName(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.StarExpr:
		return embeddedFieldName(x.X)
	case *ast.Ident:
		return x.Name
	case *ast.SelectorExpr:
		return x.Sel.Name
	case *ast.IndexExpr:
		return embeddedFieldName(x.X)
	case *ast.IndexListExpr:
		return embeddedFieldName(x.X)
	default:
		s := nodeString(e)
		if i := strings.LastIndex(s, "."); i >= 0 {
			s = s[i+1:]
		}
		if i := strings.Index(s, "["); i >= 0 {
			s = s[:i]
		}
		return strings.TrimPrefix(s, "*")
	}
}

func needsDeepCompare(r resultInfo, pkg *packageInfo) bool {
	if r.HasTypePar {
		return true
	}
	return !isDirectComparableType(r.Type, pkg)
}

func isDirectComparableType(typ string, pkg *packageInfo) bool {
	typ = strings.TrimSpace(typ)
	if builtinScalars[typ] {
		return true
	}
	if strings.HasPrefix(typ, "*") && !strings.HasPrefix(typ, "**") {
		inner := strings.TrimSpace(strings.TrimPrefix(typ, "*"))
		if strings.Contains(inner, ".") || strings.Contains(inner, "[") || strings.HasPrefix(inner, "*") {
			return false
		}
		return isScalarIdent(inner, pkg, map[string]bool{})
	}
	if strings.Contains(typ, ".") || strings.Contains(typ, "[") || strings.ContainsAny(typ, "[]{}()<- ") {
		return false
	}
	return isScalarIdent(typ, pkg, map[string]bool{})
}

func isScalarIdent(name string, pkg *packageInfo, seen map[string]bool) bool {
	if builtinScalars[name] {
		return true
	}
	if seen[name] {
		return false
	}
	seen[name] = true
	td := pkg.Types[name]
	if td == nil {
		return false
	}
	switch x := td.Expr.(type) {
	case *ast.Ident:
		return isScalarIdent(x.Name, pkg, seen)
	}
	return false
}

func resultHasError(fl *ast.FieldList, subst map[string]string) bool {
	if fl == nil {
		return false
	}
	for _, f := range fl.List {
		typ := exprString(f.Type, subst)
		if typ == "error" {
			return true
		}
	}
	return false
}

func renderFile(pkgName, existingBody string, existingImports []importSpec, funcs []funcInfo, pkg *packageInfo, opt *options) (string, error) {
	imports := map[string]importSpec{}
	bodyForUsage := existingBody
	for _, im := range existingImports {
		if im.Name == "." || im.Name == "_" || importUsed(im, bodyForUsage) {
			imports[importKey(im)] = im
		}
	}
	for _, im := range pkg.SpecialImps {
		imports[importKey(im)] = im
	}
	addImport := func(im importSpec) {
		if im.Path == "" {
			return
		}
		imports[importKey(im)] = im
	}
	addImport(importSpec{Path: "testing", Local: "testing"})
	if opt.templateName == "testify" {
		addImport(importSpec{Path: "github.com/stretchr/testify/assert", Local: "assert"})
		if testifyNeedsFmt(funcs, opt) {
			addImport(importSpec{Path: "fmt", Local: "fmt"})
		}
	} else {
		deep := false
		for _, f := range funcs {
			if f.NeedsDeep {
				deep = true
				break
			}
		}
		if deep {
			if opt.useGoCmp {
				addImport(importSpec{Path: "github.com/google/go-cmp/cmp", Local: "cmp"})
			} else {
				addImport(importSpec{Path: "reflect", Local: "reflect"})
			}
		}
	}
	// Imports referenced by generated type expressions.
	usedLocals := map[string]bool{}
	for _, f := range funcs {
		for _, p := range f.Params {
			collectSelectorLocals(p.Type, usedLocals)
		}
		for _, r := range f.Results {
			collectSelectorLocals(r.Type, usedLocals)
		}
		for _, fld := range f.Fields {
			collectSelectorLocals(fld.Type, usedLocals)
		}
		collectSelectorLocals(f.ReceiverType, usedLocals)
	}
	for local := range usedLocals {
		if local == "t" {
			// The observed generator does not import packages named t because the
			// test parameter shadows them.
			continue
		}
		if im, ok := pkg.Imports[local]; ok {
			addImport(im)
		}
	}

	var genParts []string
	for _, fi := range funcs {
		if opt.templateName == "testify" {
			genParts = append(genParts, renderTestifyFunc(fi, opt))
		} else {
			genParts = append(genParts, renderDefaultFunc(fi, opt))
		}
	}
	body := strings.TrimSpace(existingBody)
	if body != "" && len(genParts) > 0 {
		body += "\n\n" + strings.Join(genParts, "\n\n")
	} else if len(genParts) > 0 {
		body = strings.Join(genParts, "\n\n")
	}

	var src strings.Builder
	src.WriteString("package ")
	src.WriteString(pkgName)
	src.WriteString("\n\n")
	imps := importList(imports)
	if len(imps) > 0 {
		src.WriteString(formatImports(imps))
		src.WriteString("\n\n")
	}
	src.WriteString(body)
	src.WriteString("\n")
	formatted, err := format.Source([]byte(src.String()))
	if err != nil {
		return "", err
	}
	return string(formatted), nil
}

func importKey(im importSpec) string { return im.Name + "\x00" + im.Path }

func importUsed(im importSpec, body string) bool {
	if im.Name == "_" || im.Name == "." {
		return true
	}
	local := im.Local
	if local == "" {
		local = importLocal(im.Name, im.Path)
	}
	re := regexp.MustCompile(`\b` + regexp.QuoteMeta(local) + `\b`)
	return re.FindStringIndex(body) != nil
}

func collectSelectorLocals(typeStr string, used map[string]bool) {
	re := regexp.MustCompile(`\b([A-Za-z_][A-Za-z0-9_]*)\s*\.`)
	for _, m := range re.FindAllStringSubmatch(typeStr, -1) {
		used[m[1]] = true
	}
}

func testifyNeedsFmt(funcs []funcInfo, opt *options) bool {
	if !opt.printInputs && !opt.nosubtests {
		return false
	}
	for _, f := range funcs {
		if f.HasError {
			return true
		}
	}
	return false
}

func importList(m map[string]importSpec) []importSpec {
	var out []importSpec
	seen := map[string]bool{}
	for _, im := range m {
		k := importKey(im)
		if !seen[k] {
			seen[k] = true
			out = append(out, im)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		gi, gj := importGroup(out[i].Path), importGroup(out[j].Path)
		if gi != gj {
			return gi < gj
		}
		if out[i].Path != out[j].Path {
			return out[i].Path < out[j].Path
		}
		return out[i].Name < out[j].Name
	})
	return out
}

func importGroup(path string) int {
	first := path
	if i := strings.Index(path, "/"); i >= 0 {
		first = path[:i]
	}
	if strings.Contains(first, ".") {
		return 1
	}
	return 0
}

func formatImports(imps []importSpec) string {
	line := func(im importSpec) string {
		q := strconv.Quote(im.Path)
		if im.Name != "" {
			return im.Name + " " + q
		}
		return q
	}
	if len(imps) == 1 {
		return "import " + line(imps[0]) + "\n"
	}
	var b strings.Builder
	b.WriteString("import (\n")
	lastGroup := -1
	for i, im := range imps {
		g := importGroup(im.Path)
		if i > 0 && g != lastGroup {
			b.WriteString("\n")
		}
		b.WriteString("\t")
		b.WriteString(line(im))
		b.WriteString("\n")
		lastGroup = g
	}
	b.WriteString(")\n")
	return b.String()
}

func renderDefaultFunc(fi funcInfo, opt *options) string {
	var b strings.Builder
	fmt.Fprintf(&b, "func %s(t *testing.T) {\n", fi.TestName)
	if opt.parallel {
		b.WriteString("t.Parallel()\n")
	}
	writeTypesAndTests(&b, fi, opt, false)
	writeLoop(&b, fi, opt, func(bb *strings.Builder) { writeDefaultBody(bb, fi, opt) })
	b.WriteString("}\n")
	return b.String()
}

func renderTestifyFunc(fi funcInfo, opt *options) string {
	var b strings.Builder
	fmt.Fprintf(&b, "func %s(t *testing.T) {\n", fi.TestName)
	if opt.parallel {
		b.WriteString("t.Parallel()\n")
	}
	writeTypesAndTests(&b, fi, opt, true)
	writeLoop(&b, fi, opt, func(bb *strings.Builder) { writeTestifyBody(bb, fi, opt) })
	b.WriteString("}\n")
	return b.String()
}

func writeTypesAndTests(b *strings.Builder, fi funcInfo, opt *options, testify bool) {
	if fi.UseFields {
		b.WriteString("type fields struct {\n")
		for _, f := range fi.Fields {
			fmt.Fprintf(b, "%s %s\n", f.Name, f.Type)
		}
		b.WriteString("}\n")
	}
	if len(fi.Params) > 0 {
		b.WriteString("type args struct {\n")
		for _, p := range fi.Params {
			fmt.Fprintf(b, "%s %s\n", p.Name, p.Type)
		}
		b.WriteString("}\n")
	}
	if opt.named {
		b.WriteString("tests := map[string]struct {\n")
	} else {
		b.WriteString("tests := []struct {\n")
		b.WriteString("name string\n")
	}
	if fi.IsMethod {
		if fi.UseFields {
			b.WriteString("fields fields\n")
		} else {
			typeStr := fi.ReceiverType
			if fi.ReceiverPointer {
				typeStr = "*" + typeStr
			}
			fmt.Fprintf(b, "%s %s\n", fi.ReceiverVar, typeStr)
		}
	}
	if len(fi.Params) > 0 {
		b.WriteString("args args\n")
	}
	for _, r := range fi.Results {
		fmt.Fprintf(b, "%s %s\n", r.WantName, r.Type)
	}
	if fi.HasError {
		if testify {
			b.WriteString("assertion assert.ErrorAssertionFunc\n")
		} else {
			b.WriteString("wantErr bool\n")
		}
	}
	b.WriteString("}{\n")
	b.WriteString("// TODO: Add test cases.\n")
	b.WriteString("}\n")
}

func writeLoop(b *strings.Builder, fi funcInfo, opt *options, body func(*strings.Builder)) {
	if !opt.nosubtests {
		if opt.named {
			b.WriteString("for name, tt := range tests {\n")
			b.WriteString("t.Run(name, func(t *testing.T) {\n")
		} else {
			b.WriteString("for _, tt := range tests {\n")
			b.WriteString("t.Run(tt.name, func(t *testing.T) {\n")
		}
		if opt.parallel {
			b.WriteString("t.Parallel()\n")
		}
		body(b)
		b.WriteString("})\n")
		b.WriteString("}\n")
		return
	}
	needVars := loopNeedsVars(fi)
	if needVars {
		if opt.named {
			b.WriteString("for name, tt := range tests {\n")
		} else {
			b.WriteString("for _, tt := range tests {\n")
		}
	} else {
		b.WriteString("for range tests {\n")
	}
	body(b)
	b.WriteString("}\n")
}

func loopNeedsVars(fi funcInfo) bool {
	if len(fi.Params) > 0 || len(fi.Results) > 0 || fi.UseFields {
		return true
	}
	if fi.IsMethod && !fi.ReceiverIsStruct {
		return true
	}
	return false
}

func writeReceiverSetup(b *strings.Builder, fi funcInfo) string {
	if !fi.IsMethod {
		return ""
	}
	if fi.UseFields {
		typeStr := fi.ReceiverType
		prefix := ""
		if fi.ReceiverPointer {
			prefix = "&"
		}
		fmt.Fprintf(b, "%s := %s%s{\n", fi.ReceiverVar, prefix, typeStr)
		for _, f := range fi.Fields {
			fmt.Fprintf(b, "%s: tt.fields.%s,\n", f.Name, f.Name)
		}
		b.WriteString("}\n")
		return fi.ReceiverVar
	}
	if fi.ReceiverIsStruct {
		typeStr := fi.ReceiverType
		prefix := ""
		if fi.ReceiverPointer {
			prefix = "&"
		}
		fmt.Fprintf(b, "%s := %s%s{}\n", fi.ReceiverVar, prefix, typeStr)
		return fi.ReceiverVar
	}
	return "tt." + fi.ReceiverVar
}

func callExpr(fi funcInfo) string {
	var args []string
	for _, p := range fi.Params {
		a := "tt.args." + p.Name
		if p.Variadic {
			a += "..."
		}
		args = append(args, a)
	}
	argStr := strings.Join(args, ", ")
	if fi.IsMethod {
		// receiver expression is filled in by callers using a placeholder.
		return "." + fi.Name + "(" + argStr + ")"
	}
	name := fi.Name
	if len(fi.TypeArgs) > 0 {
		name += "[" + strings.Join(fi.TypeArgs, ", ") + "]"
	}
	return name + "(" + argStr + ")"
}

func callExprWithReceiver(fi funcInfo, recv string) string {
	if !fi.IsMethod {
		return callExpr(fi)
	}
	return recv + callExpr(fi)
}

func argValueExprs(fi funcInfo) []string {
	var out []string
	for _, p := range fi.Params {
		out = append(out, "tt.args."+p.Name)
	}
	return out
}

func displayCallFormat(fi funcInfo, opt *options) (string, []string) {
	name := fi.DisplayName
	vals := argValueExprs(fi)
	if opt.printInputs && len(vals) > 0 {
		return name + "(" + strings.TrimRight(strings.Repeat("%v, ", len(vals)), ", ") + ")", vals
	}
	return name + "()", nil
}

func prefixedFormat(fi funcInfo, opt *options) (string, []string) {
	base, vals := displayCallFormat(fi, opt)
	if opt.nosubtests {
		prefixVar := "tt.name"
		if opt.named {
			prefixVar = "name"
		}
		return "%q. " + base, append([]string{prefixVar}, vals...)
	}
	return base, vals
}

func writeDefaultBody(b *strings.Builder, fi funcInfo, opt *options) {
	recv := writeReceiverSetup(b, fi)
	call := callExprWithReceiver(fi, recv)
	if len(fi.Results) == 0 && !fi.HasError {
		fmt.Fprintf(b, "%s\n", call)
		return
	}
	if fi.HasError && len(fi.Results) == 0 {
		formatStr, vals := prefixedFormat(fi, opt)
		fmt.Fprintf(b, "if err := %s; (err != nil) != tt.wantErr {\n", call)
		args := append([]string{"err", "tt.wantErr"}, []string{}...)
		writeErrorf(b, opt, false, formatStr+" error = %v, wantErr %v", append(vals, args...)...)
		b.WriteString("}\n")
		return
	}
	if fi.HasError {
		vars := resultVars(fi)
		vars = append(vars, "err")
		fmt.Fprintf(b, "%s := %s\n", strings.Join(vars, ", "), call)
		formatStr, vals := prefixedFormat(fi, opt)
		b.WriteString("if (err != nil) != tt.wantErr {\n")
		if opt.nosubtests {
			writeErrorf(b, opt, false, formatStr+" error = %v, wantErr %v", append(vals, "err", "tt.wantErr")...)
			b.WriteString("continue\n")
		} else {
			writeErrorf(b, opt, true, formatStr+" error = %v, wantErr %v", append(vals, "err", "tt.wantErr")...)
		}
		b.WriteString("}\n")
		b.WriteString("if tt.wantErr {\nreturn\n}\n")
		writeComparisons(b, fi, opt)
		return
	}
	if len(fi.Results) == 1 {
		r := fi.Results[0]
		cond := compareCond(r, r.VarName)
		fmt.Fprintf(b, "if %s := %s; %s {\n", r.VarName, call, cond)
		writeCompareError(b, fi, r, opt, false)
		b.WriteString("}\n")
		return
	}
	fmt.Fprintf(b, "%s := %s\n", strings.Join(resultVars(fi), ", "), call)
	writeComparisons(b, fi, opt)
}

func resultVars(fi funcInfo) []string {
	vars := make([]string, len(fi.Results))
	for i, r := range fi.Results {
		vars[i] = r.VarName
	}
	return vars
}

func compareCond(r resultInfo, got string) string {
	if r.Deep {
		return fmt.Sprintf("!reflect.DeepEqual(%s, tt.%s)", got, r.WantName)
	}
	return fmt.Sprintf("%s != tt.%s", got, r.WantName)
}

func compareCondCmp(r resultInfo, got string) string {
	if r.Deep {
		return fmt.Sprintf("!cmp.Equal(tt.%s, %s)", r.WantName, got)
	}
	return fmt.Sprintf("%s != tt.%s", got, r.WantName)
}

func writeComparisons(b *strings.Builder, fi funcInfo, opt *options) {
	for _, r := range fi.Results {
		cond := compareCond(r, r.VarName)
		if opt.useGoCmp && r.Deep {
			cond = compareCondCmp(r, r.VarName)
		}
		fmt.Fprintf(b, "if %s {\n", cond)
		writeCompareError(b, fi, r, opt, len(fi.Results) > 1)
		b.WriteString("}\n")
	}
}

func writeCompareError(b *strings.Builder, fi funcInfo, r resultInfo, opt *options, multi bool) {
	formatStr, vals := prefixedFormat(fi, opt)
	if opt.useGoCmp && r.Deep {
		msg := formatStr
		if multi {
			msg += " " + r.VarName + " = %v, want %v\\ndiff=%s"
		} else {
			msg += " = %v, want %v\\ndiff=%s"
		}
		args := append(vals, r.VarName, "tt."+r.WantName, fmt.Sprintf("cmp.Diff(tt.%s, %s)", r.WantName, r.VarName))
		writeErrorf(b, opt, false, msg, args...)
		return
	}
	msg := formatStr
	if multi {
		msg += " " + r.VarName + " = %v, want %v"
	} else {
		msg += " = %v, want %v"
	}
	writeErrorf(b, opt, false, msg, append(vals, r.VarName, "tt."+r.WantName)...)
}

func writeErrorf(b *strings.Builder, opt *options, fatal bool, formatStr string, args ...string) {
	method := "Errorf"
	if fatal {
		method = "Fatalf"
	}
	fmt.Fprintf(b, "t.%s(%q", method, formatStr)
	for _, a := range args {
		fmt.Fprintf(b, ", %s", a)
	}
	b.WriteString(")\n")
}

func writeTestifyBody(b *strings.Builder, fi funcInfo, opt *options) {
	recv := writeReceiverSetup(b, fi)
	call := callExprWithReceiver(fi, recv)
	if len(fi.Results) == 0 && !fi.HasError {
		fmt.Fprintf(b, "%s\n", call)
		return
	}
	if fi.HasError && len(fi.Results) == 0 {
		writeAssertionCall(b, fi, opt, call, "")
		return
	}
	if fi.HasError {
		vars := resultVars(fi)
		vars = append(vars, "err")
		fmt.Fprintf(b, "%s := %s\n", strings.Join(vars, ", "), call)
		writeAssertionCall(b, fi, opt, "err", "")
		for _, r := range fi.Results {
			writeAssertEqual(b, fi, opt, r, r.VarName)
		}
		return
	}
	if len(fi.Results) == 1 {
		writeAssertEqual(b, fi, opt, fi.Results[0], call)
		return
	}
	fmt.Fprintf(b, "%s := %s\n", strings.Join(resultVars(fi), ", "), call)
	for _, r := range fi.Results {
		writeAssertEqual(b, fi, opt, r, r.VarName)
	}
}

func testifyMessage(fi funcInfo, opt *options) (string, []string) {
	base, vals := displayCallFormat(fi, opt)
	if opt.nosubtests {
		prefixVar := "tt.name"
		if opt.named {
			prefixVar = "name"
		}
		return "%q. " + base, append([]string{prefixVar}, vals...)
	}
	if opt.printInputs && len(vals) > 0 {
		return base, vals
	}
	return "", nil
}

func writeAssertEqual(b *strings.Builder, fi funcInfo, opt *options, r resultInfo, actual string) {
	msg, vals := testifyMessage(fi, opt)
	if msg == "" {
		fmt.Fprintf(b, "assert.Equal(t, tt.%s, %s)\n", r.WantName, actual)
		return
	}
	fmt.Fprintf(b, "assert.Equalf(t, tt.%s, %s, %q", r.WantName, actual, msg)
	for _, v := range vals {
		fmt.Fprintf(b, ", %s", v)
	}
	b.WriteString(")\n")
}

func writeAssertionCall(b *strings.Builder, fi funcInfo, opt *options, errExpr string, _ string) {
	msg, vals := testifyMessage(fi, opt)
	if msg == "" {
		fmt.Fprintf(b, "tt.assertion(t, %s)\n", errExpr)
		return
	}
	fmt.Fprintf(b, "tt.assertion(t, %s, fmt.Sprintf(%q", errExpr, msg)
	for _, v := range vals {
		fmt.Fprintf(b, ", %s", v)
	}
	b.WriteString("))\n")
}
EOF

gofmt -w main.go
ls -la main.go compile.sh .gitignore | sed -n '1,20p'

